export function pemToDer(pem) {
  const base64 = pem
    .replace(/-----BEGIN CERTIFICATE-----/g, '')
    .replace(/-----END CERTIFICATE-----/g, '')
    .replace(/\s+/g, '');
  return Uint8Array.from(Buffer.from(base64, 'base64'));
}

export const localhostCertDer = pemToDer(localhostCertPem);
